    WHERE p.Slot = 4 AND p.Kind = 'civcivics' AND s.Civ <> (SELECT b.Civ FROM LShufWork_Build b WHERE b.Slot = 4 AND b.OK = 1 AND b.Civ IN (SELECT Civ FROM LShufWork_CivInfo)) AND s.Age = (SELECT i.Age FROM LShufWork_CivInfo i WHERE i.Civ = (SELECT b.Civ FROM LShufWork_Build b WHERE b.Slot = 4 AND b.OK = 1 AND b.Civ IN (SELECT Civ FROM LShufWork_CivInfo))) AND s.Tree IS NOT NULL
      AND s.Civ NOT IN (SELECT b2.Civ FROM LShufWork_Build b2 WHERE b2.Slot < 4 AND b2.OK = 1 AND b2.Civ IN (SELECT Civ FROM LShufWork_CivInfo)) AND NOT 'CIVCIVC_' || s.Civ IN (SELECT PieceId FROM LShufWork_CivTaken))
  WHERE (SELECT b.Civ FROM LShufWork_Build b WHERE b.Slot = 4 AND b.OK = 1 AND b.Civ IN (SELECT Civ FROM LShufWork_CivInfo)) IS NOT NULL AND (SELECT i.Tree FROM LShufWork_CivInfo i WHERE i.Civ = (SELECT b.Civ FROM LShufWork_Build b WHERE b.Slot = 4 AND b.OK = 1 AND b.Civ IN (SELECT Civ FROM LShufWork_CivInfo))) IS NOT NULL AND NOT 'CIVCIVC_' || (SELECT b.Civ FROM LShufWork_Build b WHERE b.Slot = 4 AND b.OK = 1 AND b.Civ IN (SELECT Civ FROM LShufWork_CivInfo)) IN (SELECT PieceId FROM LShufWork_CivTaken);
DELETE FROM LShufWork_CivCSwap WHERE Slot = 4 AND (Builder IS NULL OR Source IS NULL);
INSERT OR IGNORE INTO LShufWork_CivTaken (PieceId) SELECT 'CIVCIVC_' || Builder FROM LShufWork_CivCSwap WHERE Slot = 4;
INSERT OR IGNORE INTO LShufWork_CivTaken (PieceId) SELECT 'CIVCIVC_' || Source FROM LShufWork_CivCSwap WHERE Slot = 4;
  SELECT 4, (SELECT b.Civ FROM LShufWork_Build b WHERE b.Slot = 4 AND b.OK = 1 AND b.Civ IN (SELECT Civ FROM LShufWork_CivInfo)), (SELECT MIN(p.Arg) FROM LShufWork_BuildPiece p JOIN LShufWork_CivInfo s ON s.Civ = p.Arg
    WHERE p.Slot = 4 AND p.Kind = 'civability' AND s.Civ <> (SELECT b.Civ FROM LShufWork_Build b WHERE b.Slot = 4 AND b.OK = 1 AND b.Civ IN (SELECT Civ FROM LShufWork_CivInfo)) AND s.Age = (SELECT i.Age FROM LShufWork_CivInfo i WHERE i.Civ = (SELECT b.Civ FROM LShufWork_Build b WHERE b.Slot = 4 AND b.OK = 1 AND b.Civ IN (SELECT Civ FROM LShufWork_CivInfo)))
      AND s.Civ NOT IN (SELECT b2.Civ FROM LShufWork_Build b2 WHERE b2.Slot < 4 AND b2.OK = 1 AND b2.Civ IN (SELECT Civ FROM LShufWork_CivInfo)) AND NOT 'CIVABIL_' || s.Civ IN (SELECT PieceId FROM LShufWork_CivTaken) AND NOT s.Civ IN (SELECT Civ FROM LShufWork_CivPieced))
  WHERE (SELECT b.Civ FROM LShufWork_Build b WHERE b.Slot = 4 AND b.OK = 1 AND b.Civ IN (SELECT Civ FROM LShufWork_CivInfo)) IS NOT NULL AND NOT 'CIVABIL_' || (SELECT b.Civ FROM LShufWork_Build b WHERE b.Slot = 4 AND b.OK = 1 AND b.Civ IN (SELECT Civ FROM LShufWork_CivInfo)) IN (SELECT PieceId FROM LShufWork_CivTaken) AND NOT (SELECT b.Civ FROM LShufWork_Build b WHERE b.Slot = 4 AND b.OK = 1 AND b.Civ IN (SELECT Civ FROM LShufWork_CivInfo)) IN (SELECT Civ FROM LShufWork_CivPieced);
DELETE FROM LShufWork_CivSwap WHERE Slot = 4 AND (Builder IS NULL OR Source IS NULL);
INSERT OR IGNORE INTO LShufWork_CivTaken (PieceId) SELECT 'CIVABIL_' || Builder FROM LShufWork_CivSwap WHERE Slot = 4;
INSERT OR IGNORE INTO LShufWork_CivTaken (PieceId) SELECT 'CIVABIL_' || Source FROM LShufWork_CivSwap WHERE Slot = 4;
  SELECT 4, (SELECT b.Civ FROM LShufWork_Build b WHERE b.Slot = 4 AND b.OK = 1 AND b.Civ IN (SELECT Civ FROM LShufWork_CivInfo)), u.Type, u.Civ FROM LShufWork_BuildPiece p JOIN LShufWork_CivUnique u ON u.Type = p.Arg
  WHERE p.Slot = 4 AND p.Kind = 'civunique' AND (SELECT b.Civ FROM LShufWork_Build b WHERE b.Slot = 4 AND b.OK = 1 AND b.Civ IN (SELECT Civ FROM LShufWork_CivInfo)) IS NOT NULL AND u.Civ <> (SELECT b.Civ FROM LShufWork_Build b WHERE b.Slot = 4 AND b.OK = 1 AND b.Civ IN (SELECT Civ FROM LShufWork_CivInfo))
    AND (SELECT i.Age FROM LShufWork_CivInfo i WHERE i.Civ = u.Civ) = (SELECT i.Age FROM LShufWork_CivInfo i WHERE i.Civ = (SELECT b.Civ FROM LShufWork_Build b WHERE b.Slot = 4 AND b.OK = 1 AND b.Civ IN (SELECT Civ FROM LShufWork_CivInfo))) AND NOT 'CIVUNQ_' || u.Type IN (SELECT PieceId FROM LShufWork_CivTaken);
INSERT OR IGNORE INTO LShufWork_CivTaken (PieceId) SELECT 'CIVUNQ_' || Type FROM LShufWork_CivTake WHERE Slot = 4;
  SELECT 4, (SELECT b.Civ FROM LShufWork_Build b WHERE b.Slot = 4 AND b.OK = 1 AND b.Civ IN (SELECT Civ FROM LShufWork_CivInfo)), m.PieceId, m.CivilizationType, m.BulletIndex FROM LShufWork_BuildPiece p
  JOIN LShufCivMapping m ON m.PieceId = p.PieceId JOIN LShufWork_CivInfo s ON s.Civ = m.CivilizationType
  WHERE p.Slot = 4 AND p.Kind = 'civbullet' AND (SELECT CA FROM LShufWork_Cfg) = 'LSHUF_CA_SPLIT' AND (SELECT b.Civ FROM LShufWork_Build b WHERE b.Slot = 4 AND b.OK = 1 AND b.Civ IN (SELECT Civ FROM LShufWork_CivInfo)) IS NOT NULL AND NOT 'CIVABIL_' || (SELECT b.Civ FROM LShufWork_Build b WHERE b.Slot = 4 AND b.OK = 1 AND b.Civ IN (SELECT Civ FROM LShufWork_CivInfo)) IN (SELECT PieceId FROM LShufWork_CivTaken)
    AND s.Age = (SELECT i.Age FROM LShufWork_CivInfo i WHERE i.Civ = (SELECT b.Civ FROM LShufWork_Build b WHERE b.Slot = 4 AND b.OK = 1 AND b.Civ IN (SELECT Civ FROM LShufWork_CivInfo))) AND m.Kind = 'bullet' AND m.Movable = 1 AND m.Age = s.Age AND NOT 'CIVABIL_' || s.Civ IN (SELECT PieceId FROM LShufWork_CivTaken) AND NOT m.PieceId IN (SELECT PieceId FROM LShufWork_CivTaken);
INSERT OR IGNORE INTO LShufWork_CivTaken (PieceId) SELECT PieceId FROM LShufWork_CivPTake WHERE Slot = 4;
INSERT OR IGNORE INTO LShufWork_CivPieced (Civ) SELECT Source FROM LShufWork_CivPTake WHERE Slot = 4;
CREATE TABLE IF NOT EXISTS LShufWork_CivShuf (Civ TEXT PRIMARY KEY, Age TEXT, ForA INTEGER, ARank INTEGER, AK INTEGER, APos INTEGER, AN INTEGER, ADonor TEXT, URank INTEGER, UK INTEGER, UPos INTEGER, UN INTEGER, UDonor TEXT, ForU INTEGER, CRank INTEGER, CK INTEGER, CPos INTEGER, CN INTEGER, CDonor TEXT, ForC INTEGER, HasCivics INTEGER);
DELETE FROM LShufWork_CivShuf;
    CASE WHEN (SELECT CA FROM LShufWork_Cfg) = 'LSHUF_CA_SWAPPED' AND NOT 'CIVABIL_' || i.Civ IN (SELECT PieceId FROM LShufWork_CivTaken) THEN 1 ELSE 0 END,
    CASE WHEN (SELECT CU FROM LShufWork_Cfg) = 'LSHUF_CU_SHUFFLED' THEN 1 ELSE 0 END,
    CASE WHEN i.Tree IS NOT NULL AND NOT 'CIVCIVC_' || i.Civ IN (SELECT PieceId FROM LShufWork_CivTaken) THEN 1 ELSE 0 END,
    CASE WHEN (SELECT CC FROM LShufWork_Cfg) = 'LSHUF_CC_SHUFFLED' AND i.Tree IS NOT NULL AND NOT 'CIVCIVC_' || i.Civ IN (SELECT PieceId FROM LShufWork_CivTaken) THEN 1 ELSE 0 END
  FROM LShufWork_CivInfo i WHERE i.Civ NOT IN (SELECT b.Civ FROM LShufWork_Build b WHERE b.OK = 1 AND b.Civ IS NOT NULL);
UPDATE LShufWork_CivShuf SET ARank = (SELECT COUNT(*) FROM LShufWork_CivShuf o WHERE o.Age = LShufWork_CivShuf.Age AND o.ForA = 1 AND o.Civ < LShufWork_CivShuf.Civ) WHERE ForA = 1;
UPDATE LShufWork_CivShuf SET AK = ((((((((((SELECT Seed FROM LShufWork_Cfg)) * 7919 + (13) * 104729 + (ARank) * 1299709 + 1) % 67108859) * ((((SELECT Seed FROM LShufWork_Cfg)) * 7919 + (13) * 104729 + (ARank) * 1299709 + 1) % 67108859)) + 1013904223) % 67108859) * (((((((SELECT Seed FROM LShufWork_Cfg)) * 7919 + (13) * 104729 + (ARank) * 1299709 + 1) % 67108859) * ((((SELECT Seed FROM LShufWork_Cfg)) * 7919 + (13) * 104729 + (ARank) * 1299709 + 1) % 67108859)) + 1013904223) % 67108859)) + 1664525) % 67108859),
  AN = (SELECT COUNT(*) FROM LShufWork_CivShuf o WHERE o.Age = LShufWork_CivShuf.Age AND o.ForA = 1) WHERE ForA = 1;
UPDATE LShufWork_CivShuf SET APos = (SELECT COUNT(*) FROM LShufWork_CivShuf o WHERE o.Age = LShufWork_CivShuf.Age AND o.ForA = 1
    AND (o.AK < LShufWork_CivShuf.AK OR (o.AK = LShufWork_CivShuf.AK AND o.Civ < LShufWork_CivShuf.Civ))) WHERE ForA = 1;
UPDATE LShufWork_CivShuf SET ADonor = (SELECT o.Civ FROM LShufWork_CivShuf o WHERE o.Age = LShufWork_CivShuf.Age AND o.ForA = 1 AND o.APos = (LShufWork_CivShuf.APos + 1) % LShufWork_CivShuf.AN)
  WHERE ForA = 1 AND AN >= 2;
UPDATE LShufWork_CivShuf SET URank = (SELECT COUNT(*) FROM LShufWork_CivShuf o WHERE o.Age = LShufWork_CivShuf.Age AND o.ForU = 1 AND o.Civ < LShufWork_CivShuf.Civ) WHERE ForU = 1;
UPDATE LShufWork_CivShuf SET UK = ((((((((((SELECT Seed FROM LShufWork_Cfg)) * 7919 + (14) * 104729 + (URank) * 1299709 + 1) % 67108859) * ((((SELECT Seed FROM LShufWork_Cfg)) * 7919 + (14) * 104729 + (URank) * 1299709 + 1) % 67108859)) + 1013904223) % 67108859) * (((((((SELECT Seed FROM LShufWork_Cfg)) * 7919 + (14) * 104729 + (URank) * 1299709 + 1) % 67108859) * ((((SELECT Seed FROM LShufWork_Cfg)) * 7919 + (14) * 104729 + (URank) * 1299709 + 1) % 67108859)) + 1013904223) % 67108859)) + 1664525) % 67108859),
  UN = (SELECT COUNT(*) FROM LShufWork_CivShuf o WHERE o.Age = LShufWork_CivShuf.Age AND o.ForU = 1) WHERE ForU = 1;
UPDATE LShufWork_CivShuf SET UPos = (SELECT COUNT(*) FROM LShufWork_CivShuf o WHERE o.Age = LShufWork_CivShuf.Age AND o.ForU = 1
    AND (o.UK < LShufWork_CivShuf.UK OR (o.UK = LShufWork_CivShuf.UK AND o.Civ < LShufWork_CivShuf.Civ))) WHERE ForU = 1;
UPDATE LShufWork_CivShuf SET UDonor = (SELECT o.Civ FROM LShufWork_CivShuf o WHERE o.Age = LShufWork_CivShuf.Age AND o.ForU = 1 AND o.UPos = (LShufWork_CivShuf.UPos + 1) % LShufWork_CivShuf.UN)
  WHERE ForU = 1 AND UN >= 2;
UPDATE LShufWork_CivShuf SET CRank = (SELECT COUNT(*) FROM LShufWork_CivShuf o WHERE o.Age = LShufWork_CivShuf.Age AND o.ForC = 1 AND o.Civ < LShufWork_CivShuf.Civ) WHERE ForC = 1;
UPDATE LShufWork_CivShuf SET CK = ((((((((((SELECT Seed FROM LShufWork_Cfg)) * 7919 + (15) * 104729 + (CRank) * 1299709 + 1) % 67108859) * ((((SELECT Seed FROM LShufWork_Cfg)) * 7919 + (15) * 104729 + (CRank) * 1299709 + 1) % 67108859)) + 1013904223) % 67108859) * (((((((SELECT Seed FROM LShufWork_Cfg)) * 7919 + (15) * 104729 + (CRank) * 1299709 + 1) % 67108859) * ((((SELECT Seed FROM LShufWork_Cfg)) * 7919 + (15) * 104729 + (CRank) * 1299709 + 1) % 67108859)) + 1013904223) % 67108859)) + 1664525) % 67108859),
  CN = (SELECT COUNT(*) FROM LShufWork_CivShuf o WHERE o.Age = LShufWork_CivShuf.Age AND o.ForC = 1) WHERE ForC = 1;
UPDATE LShufWork_CivShuf SET CPos = (SELECT COUNT(*) FROM LShufWork_CivShuf o WHERE o.Age = LShufWork_CivShuf.Age AND o.ForC = 1
    AND (o.CK < LShufWork_CivShuf.CK OR (o.CK = LShufWork_CivShuf.CK AND o.Civ < LShufWork_CivShuf.Civ))) WHERE ForC = 1;
UPDATE LShufWork_CivShuf SET CDonor = (SELECT o.Civ FROM LShufWork_CivShuf o WHERE o.Age = LShufWork_CivShuf.Age AND o.ForC = 1 AND o.CPos = (LShufWork_CivShuf.CPos + 1) % LShufWork_CivShuf.CN)
  WHERE ForC = 1 AND CN >= 2;
UPDATE LShufWork_CivShuf SET UDonor = ADonor WHERE (SELECT CU FROM LShufWork_Cfg) = 'LSHUF_CU_PAIRED';
UPDATE LShufWork_CivShuf SET CDonor = ADonor WHERE (SELECT CC FROM LShufWork_Cfg) = 'LSHUF_CC_PAIRED'
  AND ADonor IN (SELECT o.Civ FROM LShufWork_CivShuf o WHERE o.HasCivics = 1);
UPDATE LShufWork_CivShuf SET ADonor = NULL WHERE ADonor = Civ;
UPDATE LShufWork_CivShuf SET UDonor = NULL WHERE UDonor = Civ;
UPDATE LShufWork_CivShuf SET CDonor = NULL WHERE CDonor = Civ;
CREATE TABLE IF NOT EXISTS LShufWork_CivShufU (Civ TEXT, Type TEXT, Donor TEXT, SortIndex INTEGER, PRIMARY KEY (Civ, Type));
DELETE FROM LShufWork_CivShufU;
INSERT OR IGNORE INTO LShufWork_CivShufU (Civ, Type, Donor) SELECT s.Civ, u.Type, s.UDonor FROM LShufWork_CivShuf s
  JOIN LShufWork_CivUnique u ON u.Civ = s.UDonor WHERE s.UDonor IS NOT NULL AND NOT 'CIVUNQ_' || u.Type IN (SELECT PieceId FROM LShufWork_CivTaken);
UPDATE LShufWork_CivShufU SET SortIndex = (SELECT COUNT(*) FROM LShufWork_CivShufU o WHERE o.Civ = LShufWork_CivShufU.Civ AND (o.Type < LShufWork_CivShufU.Type)) WHERE 1 = 1;

CREATE TABLE IF NOT EXISTS LShufWork_CivPc (PieceId TEXT PRIMARY KEY, Civ TEXT, Age TEXT, BI INTEGER, Value INTEGER, DV INTEGER, Rank INTEGER, K INTEGER, DeckOrd INTEGER, Taken INTEGER);
DELETE FROM LShufWork_CivPc;
  SELECT m.PieceId, m.CivilizationType, m.Age, COALESCE(m.BulletIndex, 0), COALESCE(m.Value, 1), m.PieceId IN (SELECT PieceId FROM LShufWork_CivTaken)
  FROM LShufCivMapping m JOIN LShufWork_CivInfo i ON i.Civ = m.CivilizationType
  WHERE (SELECT CA FROM LShufWork_Cfg) = 'LSHUF_CA_SPLIT' AND m.Kind = 'bullet' AND m.Movable = 1 AND m.Age = i.Age AND NOT 'CIVABIL_' || i.Civ IN (SELECT PieceId FROM LShufWork_CivTaken);
UPDATE LShufWork_CivPc SET DV = CASE WHEN (SELECT Balanced FROM LShufWork_Cfg) = 1 THEN Value ELSE 0 END;
UPDATE LShufWork_CivPc SET Rank = (SELECT COUNT(*) FROM LShufWork_CivPc o WHERE 1 = 1 AND (o.PieceId < LShufWork_CivPc.PieceId)) WHERE 1 = 1;
UPDATE LShufWork_CivPc SET K = ((((((((((SELECT Seed FROM LShufWork_Cfg)) * 7919 + (16) * 104729 + (Rank) * 1299709 + 1) % 67108859) * ((((SELECT Seed FROM LShufWork_Cfg)) * 7919 + (16) * 104729 + (Rank) * 1299709 + 1) % 67108859)) + 1013904223) % 67108859) * (((((((SELECT Seed FROM LShufWork_Cfg)) * 7919 + (16) * 104729 + (Rank) * 1299709 + 1) % 67108859) * ((((SELECT Seed FROM LShufWork_Cfg)) * 7919 + (16) * 104729 + (Rank) * 1299709 + 1) % 67108859)) + 1013904223) % 67108859)) + 1664525) % 67108859);
UPDATE LShufWork_CivPc SET DeckOrd = (SELECT COUNT(*) FROM LShufWork_CivPc o WHERE 1 = 1 AND (o.DV > LShufWork_CivPc.DV OR (o.DV = LShufWork_CivPc.DV AND (o.K < LShufWork_CivPc.K OR (o.K = LShufWork_CivPc.K AND (o.PieceId < LShufWork_CivPc.PieceId)))))) WHERE Taken = 0;
CREATE TABLE IF NOT EXISTS LShufWork_CivPSlot (Civ TEXT PRIMARY KEY, Age TEXT, N INTEGER, Rank INTEGER, K INTEGER);
DELETE FROM LShufWork_CivPSlot;
  WHERE Civ NOT IN (SELECT Builder FROM LShufWork_CivPTake) GROUP BY Civ, Age;
UPDATE LShufWork_CivPSlot SET Rank = (SELECT COUNT(*) FROM LShufWork_CivPSlot o WHERE 1 = 1 AND (o.Civ < LShufWork_CivPSlot.Civ)) WHERE 1 = 1;
UPDATE LShufWork_CivPSlot SET K = ((((((((((SELECT Seed FROM LShufWork_Cfg)) * 7919 + (16) * 104729 + (Rank) * 1299709 + 1) % 67108859) * ((((SELECT Seed FROM LShufWork_Cfg)) * 7919 + (16) * 104729 + (Rank) * 1299709 + 1) % 67108859)) + 1013904223) % 67108859) * (((((((SELECT Seed FROM LShufWork_Cfg)) * 7919 + (16) * 104729 + (Rank) * 1299709 + 1) % 67108859) * ((((SELECT Seed FROM LShufWork_Cfg)) * 7919 + (16) * 104729 + (Rank) * 1299709 + 1) % 67108859)) + 1013904223) % 67108859)) + 1664525) % 67108859);
CREATE TABLE IF NOT EXISTS LShufWork_CivPDealt (PieceId TEXT PRIMARY KEY, Civ TEXT, FromCiv TEXT, Value INTEGER);
DELETE FROM LShufWork_CivPDealt;
DROP VIEW IF EXISTS LShufWork_CivNextPiece;
CREATE VIEW LShufWork_CivNextPiece AS SELECT c.PieceId AS PieceId, c.Civ AS FromCiv, c.Value AS Value, s.Civ AS Holder
  FROM (SELECT p.PieceId, p.Civ, p.Age, p.Value FROM LShufWork_CivPc p WHERE p.Taken = 0
    AND NOT EXISTS (SELECT 1 FROM LShufWork_CivPDealt d WHERE d.PieceId = p.PieceId) ORDER BY p.DeckOrd LIMIT 1) c
  LEFT JOIN LShufWork_CivPSlot s ON s.Age = c.Age AND (SELECT COUNT(*) FROM LShufWork_CivPDealt d WHERE d.Civ = s.Civ) < s.N
  ORDER BY CASE WHEN s.Civ = c.Civ THEN 1 ELSE 0 END,
    CASE WHEN (SELECT Balanced FROM LShufWork_Cfg) = 1 THEN (COALESCE((SELECT SUM(d.Value) FROM LShufWork_CivPDealt d WHERE d.Civ = s.Civ), 0) * 100) / s.N ELSE 0 END, s.K, s.Civ
  LIMIT 1;
CREATE TABLE IF NOT EXISTS LShufWork_CivHeld (Civ TEXT, PieceId TEXT, FromCiv TEXT, BI INTEGER, IsRest INTEGER, SortIndex INTEGER, PRIMARY KEY (Civ, PieceId));
DELETE FROM LShufWork_CivHeld;
INSERT OR IGNORE INTO LShufWork_CivHeld (Civ, PieceId, FromCiv, BI, IsRest) SELECT t.Builder, t.PieceId, t.Source, t.BI, 0 FROM LShufWork_CivPTake t;
INSERT OR IGNORE INTO LShufWork_CivHeld (Civ, PieceId, FromCiv, BI, IsRest) SELECT d.Civ, d.PieceId, d.FromCiv, p.BI, 0
  FROM LShufWork_CivPDealt d JOIN LShufWork_CivPc p ON p.PieceId = d.PieceId WHERE d.Civ IS NOT NULL;
INSERT OR IGNORE INTO LShufWork_CivHeld (Civ, PieceId, FromCiv, BI, IsRest) SELECT Civ, Civ || '__REST', Civ, 0, 1 FROM LShufWork_CivPSlot;
UPDATE LShufWork_CivHeld SET SortIndex = (SELECT COUNT(*) FROM LShufWork_CivHeld o WHERE o.Civ = LShufWork_CivHeld.Civ AND (o.IsRest < LShufWork_CivHeld.IsRest OR (o.IsRest = LShufWork_CivHeld.IsRest AND (o.FromCiv < LShufWork_CivHeld.FromCiv OR (o.FromCiv = LShufWork_CivHeld.FromCiv AND (o.BI < LShufWork_CivHeld.BI OR (o.BI = LShufWork_CivHeld.BI AND (o.PieceId < LShufWork_CivHeld.PieceId)))))))) WHERE 1 = 1;

UPDATE LShufWork_CivTake SET SortIndex = (SELECT COUNT(*) FROM LShufWork_CivTake o WHERE o.Slot = LShufWork_CivTake.Slot AND (o.Type < LShufWork_CivTake.Type)) WHERE 1 = 1;
DELETE FROM LShufResultCivPieces;
INSERT OR IGNORE INTO LShufResultCivPieces (CivilizationType, PieceId, FromCivilization, Kind, SortIndex) SELECT Builder, 'CIVABIL_' || Source, Source, 'ability', 0 FROM LShufWork_CivSwap;
INSERT OR IGNORE INTO LShufResultCivPieces (CivilizationType, PieceId, FromCivilization, Kind, SortIndex) SELECT Source, 'CIVABIL_' || Builder, Builder, 'ability', 0 FROM LShufWork_CivSwap;
INSERT OR IGNORE INTO LShufResultCivPieces (CivilizationType, PieceId, FromCivilization, Kind, SortIndex) SELECT Builder, 'CIVCIVC_' || Source, Source, 'civics', 0 FROM LShufWork_CivCSwap;
INSERT OR IGNORE INTO LShufResultCivPieces (CivilizationType, PieceId, FromCivilization, Kind, SortIndex) SELECT Source, 'CIVCIVC_' || Builder, Builder, 'civics', 0 FROM LShufWork_CivCSwap;
INSERT OR IGNORE INTO LShufResultCivPieces (CivilizationType, PieceId, FromCivilization, Kind, SortIndex) SELECT Builder, 'CIVUNQ_' || Type, Source, 'unique', SortIndex + 1 FROM LShufWork_CivTake;
INSERT OR IGNORE INTO LShufResultCivPieces (CivilizationType, PieceId, FromCivilization, Kind, SortIndex) SELECT Civ, 'CIVABIL_' || ADonor, ADonor, 'ability', 0 FROM LShufWork_CivShuf WHERE ADonor IS NOT NULL;
INSERT OR IGNORE INTO LShufResultCivPieces (CivilizationType, PieceId, FromCivilization, Kind, SortIndex) SELECT Civ, 'CIVCIVC_' || CDonor, CDonor, 'civics', 0 FROM LShufWork_CivShuf WHERE CDonor IS NOT NULL;
INSERT OR IGNORE INTO LShufResultCivPieces (CivilizationType, PieceId, FromCivilization, Kind, SortIndex) SELECT Civ, 'CIVUNQ_' || Type, Donor, 'unique', SortIndex + 1 FROM LShufWork_CivShufU;
INSERT OR IGNORE INTO LShufResultCivPieces (CivilizationType, PieceId, FromCivilization, Kind, SortIndex) SELECT Civ, PieceId, FromCiv, CASE WHEN IsRest = 1 THEN 'remainder' ELSE 'bullet' END, SortIndex FROM LShufWork_CivHeld;
  SELECT 'CivBuilder' || CASE WHEN b.Slot = 1 THEN '' ELSE CAST(b.Slot AS TEXT) END, CASE WHEN b.OK = 0 THEN b.Why
    WHEN b.Civ IS NULL OR b.Civ NOT IN (SELECT Civ FROM LShufWork_CivInfo) THEN 'builder-not-in-game'
    WHEN NOT EXISTS (SELECT 1 FROM LShufWork_CivSwap s WHERE s.Slot = b.Slot)
      AND NOT EXISTS (SELECT 1 FROM LShufWork_CivCSwap s WHERE s.Slot = b.Slot)
      AND NOT EXISTS (SELECT 1 FROM LShufWork_CivTake t WHERE t.Slot = b.Slot)
      AND NOT EXISTS (SELECT 1 FROM LShufWork_CivPTake t WHERE t.Slot = b.Slot) THEN 'no-pieces'
    ELSE 'ok' END FROM LShufWork_Build b ORDER BY b.Slot;
